<script setup>
import { ref,computed,onMounted } from 'vue';
import { api } from '../../services/api.js';
import { workspace } from '../../services/workspace.js';
import { shortDate,money } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
const data=ref(null),loading=ref(true),error=ref('');
const entitlement=computed(()=>data.value?.entitlement||{});
const message=computed(()=>`¡Hola! Quiero consultar por los planes de Mi Tienda Ya. Mi correo es ${data.value?.user?.email||''}.`);
const days=computed(()=>Math.max(0,Math.ceil((new Date(entitlement.value.expiresAt).getTime()-Date.now())/86400000)));
const waLink=computed(()=>{const phone=data.value?.contact?.whatsapp||data.value?.contact?.phone;return phone?`https://wa.me/${phone.replace(/\D/g,'')}?text=${encodeURIComponent(message.value)}`:''});
onMounted(async()=>{try{data.value=await api.get('/me/plan')}catch(e){error.value=e.message}finally{loading.value=false}});
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">VAMOS POR MÁS</p><h1>Tu plan</h1><p>Conocé lo que tenés disponible y elegí cómo seguir creciendo.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><template v-else-if="data"><section class="p-plan-hero"><div><span class="p-badge">{{entitlement.trial?'Período de prueba':entitlement.allowed?'Plan activo':'Tu próximo paso'}}</span><h2>{{entitlement.trial?'Conocé todo lo que podés hacer.':data.plan?.name||'Tu tienda está esperando brillar.'}}</h2><p>{{entitlement.allowed?`Disponible hasta el ${shortDate(entitlement.expiresAt)}`:'Podés seguir administrando tus productos. Activá un plan para publicar tu tienda y recibir pedidos.'}}</p></div><div><Icon name="crown" :size="64" style="color:#b4d3ae"/></div></section><div class="p-plan-details"><article class="p-plan-detail"><span>Tiempo disponible</span><strong>{{entitlement.allowed?`${days} ${days===1?'día':'días'}`:'Plan pendiente'}}</strong></article><article class="p-plan-detail"><span>Tiendas incluidas</span><strong>{{workspace.stores.length}} / {{entitlement.maxStores||data.plan?.maxStores||1}}</strong></article><article class="p-plan-detail"><span>Productos por tienda</span><strong>{{entitlement.maxProducts===0?'Ilimitados':entitlement.maxProducts??data.plan?.maxProducts??'—'}}</strong></article></div><div class="p-dashboard-grid"><section class="p-section-card"><div class="p-section-title"><div><h2>{{entitlement.trial?'Todo listo para dar el primer paso':'Lo que incluye tu plan'}}</h2><p>{{data.plan?`${money(data.plan.price)} cada ${data.plan.durationDays} días`:'Prepará tu catálogo y conocé las herramientas de tu tienda.'}}</p></div></div><ul class="p-mini-list"><li v-for="(feature,i) in data.plan?.features?.length?data.plan.features:['Productos físicos y digitales','Personalización de tienda, carrito y checkout','Gestión de pedidos y stock','Cobros y entregas a tu medida']" :key="i"><Icon name="check" :size="16"/>{{feature}}</li></ul></section><section class="p-section-card"><div class="p-section-title"><div><h2>¿Querés cambiar o renovar tu plan?</h2><p>Hablemos de lo que necesita tu emprendimiento.</p></div></div><p class="p-help" style="margin-bottom:20px">Escribinos para consultar opciones, sumar tiendas o renovar. Te acompañamos a elegir tu próximo paso.</p><div style="display:flex;flex-direction:column;gap:10px"><a v-if="waLink" :href="waLink" class="btn btn-primary" target="_blank" rel="noopener"><Icon name="whatsapp" :size="17"/>Consultar por WhatsApp</a><a v-if="data.contact?.email" :href="`mailto:${data.contact.email}?subject=${encodeURIComponent('Consulta sobre mi plan')}&body=${encodeURIComponent(message)}`" class="btn btn-secondary"><Icon name="mail" :size="17"/>Enviar un correo</a><p v-if="!waLink&&!data.contact?.email" class="p-info">La administración todavía no configuró sus datos de contacto. Consultá a quien te asignó la tienda.</p></div></section></div><div v-if="!entitlement.allowed" class="p-info p-warning"><strong>Tu contenido se conserva.</strong> Podés crear y editar productos, categorías y diseño. Para publicar o recibir compras necesitás una prueba o un plan vigente.</div></template></div></template>
